113	// 新首次到期日须严格晚于所有未撤销完成的实际完成日；已撤销完成不再限制；
114	// 没有有效完成则无此限制。
115	func TestAdjustFirstDueAfterValidCompletions(t *testing.T) {
116		s := newTestStore(t)
117		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
118			t.Fatal(err)
119		}
120		if _, err := s.createPlan("EQ-1", "更换滤芯", "2026-01-01", 30); err != nil {
121			t.Fatal(err)
122		}
123		_, _, doneSeq, err := s.completePlan("EQ-1", "2026-01-01", "2026-01-10", "已更换")
124		if err != nil {
125			t.Fatal(err)
126		}
127		// 等于或早于有效完成的实际完成日均拒绝。
128		for _, bad := range []string{"2026-01-10", "2026-01-09", "2025-12-31"} {
129			if _, _, err := s.adjustPlan("EQ-1", "新内容", bad, 60, "理由"); !errors.Is(err, errConflict) {
130				t.Fatalf("新首次到期日 %s 应失败，得到 %v", bad, err)
131			}
132		}
133		if _, _, err := s.adjustPlan("EQ-1", "新内容", "2026-01-11", 60, "理由"); err != nil {
134			t.Fatalf("晚于完成日的调整应成功: %v", err)
135		}
136		// 旧段完成不能再撤销，其完成日仍参与限制（仍属未撤销完成）。
137		if _, _, err := s.revokeCompletion("EQ-1", doneSeq, "误登记"); !errors.Is(err, errConflict) {
138			t.Fatalf("旧段完成应不能撤销，得到 %v", err)
139		}
140		// 在当前段完成再撤销：已撤销的完成日不再限制下一次调整。
141		if _, _, _, err := s.completePlan("EQ-1", "2026-01-11", "2026-02-01", "已更换"); err != nil {
142			t.Fatal(err)
143		}
144		_, _, doneSeq2, err := s.completePlan("EQ-1", "2026-03-12", "2026-03-15", "已更换")
145		if err != nil {
146			t.Fatal(err)
147		}
148		if _, _, err := s.revokeCompletion("EQ-1", doneSeq2, "误登记"); err != nil {
149			t.Fatalf("撤销当前段最新完成: %v", err)
150		}
151		// 未撤销完成的完成日为 2026-02-01（01-11 段）与 2026-01-10（旧段）：
152		// 新首次日 2026-02-02 合法（已撤销的 03-15 不限制）。
153		if _, _, err := s.adjustPlan("EQ-1", "再调整", "2026-02-02", 30, "理由"); err != nil {
154			t.Fatalf("已撤销完成不应限制调整: %v", err)
