158	// 跨段撤销：调整开启新方案段后，旧段完成不能再撤销；当前段可连续撤销，
159	// 恢复目标完成的周期到期日；同周期重新完成生成新序号，旧序号不能误撤销新完成。
160	func TestAdjustSegmentRevoke(t *testing.T) {
161		s := newTestStore(t)
162		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
163			t.Fatal(err)
164		}
165		if _, err := s.createPlan("EQ-1", "更换滤芯", "2026-01-01", 30); err != nil {
166			t.Fatal(err)
167		}
168		_, _, oldSeq, err := s.completePlan("EQ-1", "2026-01-01", "2026-01-02", "旧段完成")
169		if err != nil {
170			t.Fatal(err)
171		}
172		if _, _, err := s.adjustPlan("EQ-1", "更换高效滤芯", "2026-02-01", 60, "方案升级"); err != nil {
173			t.Fatal(err)
174		}
175		// 旧段完成不能再撤销。
176		if _, _, err := s.revokeCompletion("EQ-1", oldSeq, "想撤销旧段"); !errors.Is(err, errConflict) {
177			t.Fatalf("旧段完成应不能撤销，得到 %v", err)
178		}
179		// 当前段完成两次，只能先撤销最新的一次。
180		_, _, seq1, err := s.completePlan("EQ-1", "2026-02-01", "2026-02-03", "第一次")
181		if err != nil {
182			t.Fatal(err)
183		}
184		_, _, seq2, err := s.completePlan("EQ-1", "2026-04-02", "2026-04-05", "第二次")
185		if err != nil {
186			t.Fatal(err)
187		}
188		if _, _, err := s.revokeCompletion("EQ-1", seq1, "跳序撤销"); !errors.Is(err, errConflict) {
189			t.Fatalf("存在更晚有效完成时应拒绝，得到 %v", err)
190		}
191		p, target, err := s.revokeCompletion("EQ-1", seq2, "误登记")
192		if err != nil {
193			t.Fatalf("撤销最新完成: %v", err)
194		}
195		if p.NextDue != "2026-04-02" || target.Due != "2026-04-02" {
196			t.Fatalf("恢复下一到期日 = %q，想得到 2026-04-02", p.NextDue)
197		}
198		// 连续撤销本段：再撤销 seq1，下一到期日恢复为其周期到期日。
199		p, _, err = s.revokeCompletion("EQ-1", seq1, "继续撤销")
200		if err != nil {
201			t.Fatalf("连续撤销本段: %v", err)
202		}
203		if p.NextDue != "2026-02-01" {
204			t.Fatalf("下一到期日 = %q，想得到 2026-02-01", p.NextDue)
205		}
206		// 旧段完成依然不能撤销。
207		if _, _, err := s.revokeCompletion("EQ-1", oldSeq, "再试旧段"); !errors.Is(err, errConflict) {
208			t.Fatalf("旧段完成仍应不能撤销，得到 %v", err)
209		}
210		// 同周期重新完成生成新序号；旧序号不能误撤销新完成。
211		_, _, seq3, err := s.completePlan("EQ-1", "2026-02-01", "2026-02-04", "重新完成")
212		if err != nil {
213			t.Fatal(err)
214		}
215		if seq3 == seq1 {
216			t.Fatal("重新完成应生成新序号")
217		}
218		if _, _, err := s.revokeCompletion("EQ-1", seq1, "旧序号"); !errors.Is(err, errConflict) {
219			t.Fatalf("旧序号的再次撤销应被拒绝，得到 %v", err)
220		}
221		if got := s.findPlan("EQ-1"); got.NextDue != "2026-04-02" {
222			t.Fatalf("旧序号撤销不应影响新完成，下一到期日 = %q", got.NextDue)
223		}
224		// 原完成的内容、日期、时间及撤销状态保留。
225		events := s.eventsOf("EQ-1")
226		var oldDone, redone *Event
227		revoked := s.revokedDoneSeqs()
228		for i := range events {
229			if events[i].Seq == oldSeq {
230				oldDone = &events[i]
231			}
232			if events[i].Seq == seq3 {
233				redone = &events[i]
234			}
235		}
236		if oldDone == nil || oldDone.Content != "旧段完成" || oldDone.Done != "2026-01-02" || oldDone.Time.IsZero() {
237			t.Fatalf("旧段完成履历应保留: %+v", oldDone)
238		}
239		if !revoked[seq1] || !revoked[seq2] || revoked[seq3] || revoked[oldSeq] {
240			t.Fatalf("撤销状态不对: %v", revoked)
241		}
242		if redone == nil || redone.Content != "重新完成" {
243			t.Fatalf("重新完成的履历应保留: %+v", redone)
244		}
245		// 重启后段边界与撤销规则保持。
246		s = saveAndReopen(t, s)
247		if _, _, err := s.revokeCompletion("EQ-1", oldSeq, "重开后试旧段"); !errors.Is(err, errConflict) {
248			t.Fatalf("重开后旧段完成仍应不能撤销，得到 %v", err)
249		}
250		if _, _, err := s.revokeCompletion("EQ-1", seq3, "重开后撤销当前段"); err != nil {
251			t.Fatalf("重开后应能撤销当前段最新完成: %v", err)
252		}
253		if got := s.findPlan("EQ-1"); got.NextDue != "2026-02-01" {
254			t.Fatalf("重开后恢复下一到期日 = %q，想得到 2026-02-01", got.NextDue)
255		}
256	}
257	
258	// 调整后 maintain 只完成当前段下一周期，按本段首次日加整数倍间隔推进到严格
259	// 晚于完成日的最早日期；日期越界整次拒绝。
260	func TestAdjustSegmentCompleteDelayed(t *testing.T) {
261		s := newTestStore(t)
262		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
263			t.Fatal(err)
264		}
265		if _, err := s.createPlan("EQ-1", "更换滤芯", "2026-01-01", 10); err != nil {
266			t.Fatal(err)
267		}
268		if _, _, err := s.adjustPlan("EQ-1", "更换高效滤芯", "2026-02-01", 7, "方案升级"); err != nil {
269			t.Fatal(err)
270		}
271		// 旧段的下一到期日不再可登记：所填到期日须等于当前下一到期日 2026-02-01。
272		if _, _, _, err := s.completePlan("EQ-1", "2026-01-01", "2026-02-05", "旧周期"); !errors.Is(err, errConflict) {
273			t.Fatalf("旧段周期应不能登记，得到 %v", err)
274		}
275		// 延期到 2026-02-20 完成：按本段首次日 2026-02-01 加整数倍 7 天推进，
276		// 严格晚于 02-20 的最早日期为 2026-02-22（02-01 + 3*7）。
277		p, next, _, err := s.completePlan("EQ-1", "2026-02-01", "2026-02-20", "已更换")
278		if err != nil {
279			t.Fatalf("completePlan: %v", err)
280		}
281		if next != "2026-02-22" || p.NextDue != "2026-02-22" {
282			t.Fatalf("下一到期日 = %q，想得到 2026-02-22", next)
283		}
284		// 日期越界整次拒绝：完成日接近年末，下一到期日超出 9999-12-31。
285		if _, _, err := s.adjustPlan("EQ-1", "年末方案", "9999-12-30", 10, "年末调整"); err != nil {
286			t.Fatal(err)
287		}
288		if _, _, _, err := s.completePlan("EQ-1", "9999-12-30", "9999-12-30", "越界"); !errors.Is(err, errConflict) {
289			t.Fatalf("下一到期日越界应整次拒绝，得到 %v", err)
290		}
291		if got := s.findPlan("EQ-1"); got.NextDue != "9999-12-30" {
292			t.Fatalf("越界拒绝不应推进下一到期日，得到 %q", got.NextDue)
293		}
294		if got := len(s.eventsOf("EQ-1")); got != 4 {
295			t.Fatalf("越界拒绝不应产生完成履历，履历数 = %d", got)
296		}
297	}
298	
299	// 维修中、停用时也允许调整；调整不改变资产状态、工单或请求绑定。
300	func TestAdjustWhileRepairingOrDeactivated(t *testing.T) {
301		s := newTestStore(t)
302		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
303			t.Fatal(err)
304		}
305		if _, err := s.createPlan("EQ-1", "更换滤芯", "2026-11-01", 90); err != nil {
306			t.Fatal(err)
307		}
308		// 维修中允许调整，资产状态与工单不变。
309		tk, _, err := s.report("EQ-1", "卡纸", "req-1")
310		if err != nil {
311			t.Fatal(err)
312		}
313		if _, _, err := s.adjustPlan("EQ-1", "维修中调整", "2026-12-01", 30, "理由"); err != nil {
314			t.Fatalf("维修中调整应成功: %v", err)
315		}
316		if a := s.findAsset("EQ-1"); a.Status != statusRepairing {
317			t.Fatalf("调整不应改变资产状态: %s", a.Status)
318		}
319		if got := s.openTicketOf("EQ-1"); got == nil || got.ID != tk.ID {
320			t.Fatal("调整不应改变工单")
321		}
322		if _, _, err := s.closeTicket(tk.ID, "已修复"); err != nil {
323			t.Fatal(err)
324		}
325		// 停用时允许调整，但停用资产仍不参与 due、不能登记完成。
326		if _, err := s.deactivateAsset("EQ-1", "设备调拨"); err != nil {
327			t.Fatal(err)
328		}
329		if _, _, err := s.adjustPlan("EQ-1", "停用中调整", "2027-01-01", 60, "理由"); err != nil {
330			t.Fatalf("停用中调整应成功: %v", err)
331		}
332		if a := s.findAsset("EQ-1"); a.Status != statusDeactivated {
333			t.Fatalf("调整不应改变资产状态: %s", a.Status)
334		}
335		if _, _, _, err := s.completePlan("EQ-1", "2027-01-01", "2027-01-01", "结果"); !errors.Is(err, errConflict) {
336			t.Fatalf("停用期间不能登记完成，得到 %v", err)
337		}
338		var buf bytes.Buffer
339		if err := cmdDue([]string{"--data-dir", s.dir, "--date", "2027-06-01"}, &buf); err != nil {
340			t.Fatal(err)
341		}
342		if strings.Contains(buf.String(), "EQ-1") {
343			t.Fatalf("停用资产不应参与 due:\n%s", buf.String())
344		}
345		if err := s.save(); err != nil {
346			t.Fatal(err)
347		}
348	}
349	
350	// 导入接续：源台账含多次调整与跨段完成，导入后段边界、顺序与当前方案保持，
351	// 可继续调整、完成与撤销；源只读，目标原有记录不变。
352	func TestImportWithAdjustContinuation(t *testing.T) {
353		src := newTestStore(t)
354		if _, err := src.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
355			t.Fatal(err)
356		}
357		if _, err := src.createPlan("EQ-1", "更换滤芯", "2026-01-01", 30); err != nil {
358			t.Fatal(err)
359		}
360		_, _, oldSeq, err := src.completePlan("EQ-1", "2026-01-01", "2026-01-05", "旧段完成")
361		if err != nil {
362			t.Fatal(err)
363		}
364		if _, _, err := src.adjustPlan("EQ-1", "更换高效滤芯", "2026-02-01", 60, "方案升级"); err != nil {
365			t.Fatal(err)
366		}
367		_, _, curSeq, err := src.completePlan("EQ-1", "2026-02-01", "2026-02-03", "当前段完成")
368		if err != nil {
369			t.Fatal(err)
370		}
371		if err := src.save(); err != nil {
372			t.Fatal(err)
373		}
374		srcRaw, err := os.ReadFile(filepath.Join(src.dir, dataFileName))
375		if err != nil {
376			t.Fatal(err)
377		}
378	
379		// 目标已有其他资产的记录。
380		dst := newTestStore(t)
381		if _, err := dst.registerAsset("EQ-9", "空调", "三楼"); err != nil {
382			t.Fatal(err)
383		}
384		if _, err := dst.createPlan("EQ-9", "清洗滤网", "2026-03-01", 15); err != nil {
385			t.Fatal(err)
386		}
387		if err := dst.save(); err != nil {
388			t.Fatal(err)
389		}
390	
391		outcome, err := importAssets(dst.dir, src.dir, []string{"EQ-1"})
392		if err != nil {
393			t.Fatalf("importAssets: %v", err)
394		}
395		if outcome.plans != 1 || len(outcome.completions) != 2 {
396			t.Fatalf("导入结果不对: %+v", outcome)
397		}
398		// 源文件字节不变。
399		got, err := os.ReadFile(filepath.Join(src.dir, dataFileName))
400		if err != nil || !bytes.Equal(got, srcRaw) {
401			t.Fatal("源台账应保持只读")
402		}
403		d, err := openStore(dst.dir)
404		if err != nil {
405			t.Fatal(err)
406		}
407		// 目标原有记录不变。
408		if p := d.findPlan("EQ-9"); p == nil || p.Content != "清洗滤网" || p.NextDue != "2026-03-01" {
409			t.Fatalf("目标原有计划不应改变: %+v", p)
410		}
411		// 当前方案与下一到期日原样复制。
412		p := d.findPlan("EQ-1")
413		if p == nil || p.Content != "更换高效滤芯" || p.FirstDue != "2026-02-01" ||
414			p.IntervalDays != 60 || p.NextDue != "2026-04-02" {
415			t.Fatalf("导入后计划不对: %+v", p)
416		}
417		// 段边界保持：旧段完成（重编号后）不能撤销；当前段完成可撤销。
418		var newOldSeq, newCurSeq int
419		for _, m := range outcome.completions {
420			if m.OldSeq == oldSeq {
421				newOldSeq = m.NewSeq
422			}
423			if m.OldSeq == curSeq {
424				newCurSeq = m.NewSeq
425			}
426		}
427		if newOldSeq == 0 || newCurSeq == 0 || newOldSeq == newCurSeq {
428			t.Fatalf("完成序号映射不对: %+v", outcome.completions)
429		}
430		if _, _, err := d.revokeCompletion("EQ-1", newOldSeq, "试旧段"); !errors.Is(err, errConflict) {
431			t.Fatalf("导入后旧段完成应不能撤销，得到 %v", err)
432		}
433		if _, _, err := d.revokeCompletion("EQ-1", newCurSeq, "误登记"); err != nil {
434			t.Fatalf("导入后应能撤销当前段完成: %v", err)
435		}
436		if got := d.findPlan("EQ-1"); got.NextDue != "2026-02-01" {
437			t.Fatalf("撤销后下一到期日 = %q，想得到 2026-02-01", got.NextDue)
438		}
439		// 导入后可继续完成与调整。
440		if _, next, _, err := d.completePlan("EQ-1", "2026-02-01", "2026-02-10", "导入后完成"); err != nil || next != "2026-04-02" {
441			t.Fatalf("导入后完成: next=%q err=%v", next, err)
442		}
443		if _, _, err := d.adjustPlan("EQ-1", "再次升级", "2026-05-01", 45, "导入后调整"); err != nil {
444			t.Fatalf("导入后调整: %v", err)
445		}
446		if err := d.save(); err != nil {
447			t.Fatal(err)
448		}
449		// 重载后仍一致。
450		if _, err := openStore(dst.dir); err != nil {
451			t.Fatalf("导入后继续操作应通过一致性检查: %v", err)
452		}
453	}
454	
455	// 矛盾台账：调整履历与当时方案不符、新首次日未晚于有效完成日、保存方案与
456	// 履历推出的当前方案不符、撤销旧段完成等，所有读写命令拒绝并保留原文件。
457	func TestContradictoryAdjustLedger(t *testing.T) {
458		// 合法基底：建立 + 完成 + 调整，履历序号有间隔、数组乱序仍合法。
459		base := `{
460		  "version": 1,
461		  "assets": [{"id":"EQ-1","name":"打印机","location":"一楼","status":"可用"}],
462		  "tickets": [],
463		  "events": [
464		    {"seq":7,"asset_id":"EQ-1","kind":"保养调整","content":"方案升级","due":"2026-02-01","interval":60,"new_content":"更换高效滤芯","old_content":"更换滤芯","old_due":"2026-01-01","old_interval":30,"old_next_due":"2026-01-31","time":"2026-02-01T08:00:00Z"},
465		    {"seq":2,"asset_id":"EQ-1","kind":"保养建立","content":"更换滤芯","due":"2026-01-01","interval":30,"time":"2026-01-01T08:00:00Z"},
466		    {"seq":5,"asset_id":"EQ-1","kind":"保养完成","content":"已更换","due":"2026-01-01","done":"2026-01-10","time":"2026-01-10T08:00:00Z"}
467		  ],
468		  "requests": [],
469		  "plans": [{"asset_id":"EQ-1","content":"更换高效滤芯","first_due":"2026-02-01","interval_days":60,"next_due":"2026-02-01"}],
470		  "next_ticket_seq": 1
471		}`
472		write := func(t *testing.T, dir string, mutate func(m map[string]any)) []byte {
473			t.Helper()
474			var m map[string]any
475			if err := json.Unmarshal([]byte(base), &m); err != nil {
476				t.Fatal(err)
477			}
478			if mutate != nil {
479				mutate(m)
480			}
481			raw, err := json.Marshal(m)
482			if err != nil {
483				t.Fatal(err)
484			}
485			if err := os.WriteFile(filepath.Join(dir, dataFileName), raw, 0o644); err != nil {
486				t.Fatal(err)
487			}
488			return raw
489		}
490		events := func(m map[string]any) []any { return m["events"].([]any) }
491		adjust := func(m map[string]any) map[string]any { return events(m)[0].(map[string]any) }
492	
493		// 合法基底可直接使用：数组乱序、序号间隔合法。
494		dir := t.TempDir()
495		write(t, dir, nil)
496		s, err := openStore(dir)
497		if err != nil {
498			t.Fatalf("合法台账应能加载: %v", err)
499		}
500		if p := s.findPlan("EQ-1"); p.NextDue != "2026-02-01" || p.IntervalDays != 60 {
501			t.Fatalf("合法台账计划不对: %+v", p)
502		}
503	
504		cases := []struct {
505			name   string
506			mutate func(m map[string]any)
507		}{
508			{"调整记录的原方案与当时方案不符", func(m map[string]any) {
509				adjust(m)["old_interval"] = 31
510			}},
511			{"调整记录的原下一到期日不符", func(m map[string]any) {
512				adjust(m)["old_next_due"] = "2026-01-30"
513			}},
514			{"新首次日未严格晚于有效完成日", func(m map[string]any) {
515				adjust(m)["due"] = "2026-01-10"
516				m["plans"].([]any)[0].(map[string]any)["first_due"] = "2026-01-10"
517				m["plans"].([]any)[0].(map[string]any)["next_due"] = "2026-01-10"
518			}},
519			{"保存方案与履历推出的当前方案不符", func(m map[string]any) {
520				m["plans"].([]any)[0].(map[string]any)["interval_days"] = 61
521			}},
522			{"保存的下一到期日与履历不符", func(m map[string]any) {
523				m["plans"].([]any)[0].(map[string]any)["next_due"] = "2026-02-02"
524			}},
525			{"撤销旧段完成", func(m map[string]any) {
526				appendTo(m, "events", map[string]any{
527					"seq": 9, "asset_id": "EQ-1", "kind": "保养撤销",
528					"content": "撤销旧段", "target_seq": 5, "time": "2026-02-02T08:00:00Z",
529				})
530			}},
531			{"调整后完成履历不接续当前段", func(m map[string]any) {
532				appendTo(m, "events", map[string]any{
533					"seq": 9, "asset_id": "EQ-1", "kind": "保养完成",
534					"content": "旧段周期", "due": "2026-01-31", "done": "2026-02-05",
535					"time": "2026-02-05T08:00:00Z",
536				})
537				m["plans"].([]any)[0].(map[string]any)["next_due"] = "2026-04-02"
538			}},
539			{"调整履历缺少原方案字段", func(m map[string]any) {
540				delete(adjust(m), "old_content")
541			}},
542		}
543		for _, tc := range cases {
544			t.Run(tc.name, func(t *testing.T) {
545				dir := t.TempDir()
546				raw := write(t, dir, tc.mutate)
547				if _, err := openStore(dir); err == nil {
548					t.Fatal("矛盾台账应拒绝加载")
549				}
550				// 所有读写命令拒绝：查询与写入都以退出码 1 失败。
551				var out, errBuf bytes.Buffer
552				if code := run([]string{"detail", "--data-dir", dir, "--asset-id", "EQ-1"}, &out, &errBuf); code != 1 {
553					t.Fatalf("detail 应以退出码 1 失败，得到 %d", code)
554				}
555				out.Reset()
556				if code := run([]string{"adjust", "--data-dir", dir, "--asset-id", "EQ-1",
557					"--content", "x", "--first-due", "2027-01-01", "--interval-days", "30", "--reason", "r"},
558					&out, &errBuf); code != 1 {
559					t.Fatalf("adjust 应以退出码 1 失败，得到 %d", code)
560				}
561				// 原文件字节保留，不自动修复。
562				got, err := os.ReadFile(filepath.Join(dir, dataFileName))
563				if err != nil || !bytes.Equal(got, raw) {
564					t.Fatal("矛盾台账的原文件应保持不变")
565				}
566			})
567		}
568	}
569	
570	// 失败重载：失败的调整不产生履历、不消耗序号、不改变计划；成功调整原子保存，
571	// 重载后方案与段边界保持。
572	func TestAdjustFailureAndReload(t *testing.T) {
573		s := newTestStore(t)
574		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
575			t.Fatal(err)
576		}
577		if _, err := s.createPlan("EQ-1", "更换滤芯", "2026-01-01", 30); err != nil {
578			t.Fatal(err)
579		}
580		if _, _, _, err := s.completePlan("EQ-1", "2026-01-01", "2026-01-10", "已更换"); err != nil {
581			t.Fatal(err)
582		}
583		if err := s.save(); err != nil {
584			t.Fatal(err)
585		}
586		before, err := os.ReadFile(filepath.Join(s.dir, dataFileName))
587		if err != nil {
588			t.Fatal(err)
589		}
590		eventCount := len(s.data.Events)
591	
592		// 失败的调整：新首次日未严格晚于有效完成日。
593		if _, _, err := s.adjustPlan("EQ-1", "新内容", "2026-01-10", 60, "理由"); !errors.Is(err, errConflict) {
594			t.Fatalf("应拒绝，得到 %v", err)
595		}
596		if len(s.data.Events) != eventCount {
597			t.Fatal("失败的调整不应产生履历")
598		}
599		if p := s.findPlan("EQ-1"); p.Content != "更换滤芯" || p.NextDue != "2026-01-31" {
600			t.Fatalf("失败的调整不应改变计划: %+v", p)
601		}
602		// 失败不写文件：磁盘上的台账字节保持不变。
603		gotRaw, err := os.ReadFile(filepath.Join(s.dir, dataFileName))
604		if err != nil || !bytes.Equal(gotRaw, before) {
605			t.Fatal("失败的调整不应改动台账文件")
606		}
607		// 不消耗序号：随后的成功操作使用紧接着的序号。
608		p, _, err := s.adjustPlan("EQ-1", "更换高效滤芯", "2026-01-11", 60, "型号升级")
609		if err != nil {
610			t.Fatalf("adjustPlan: %v", err)
611		}
612		events := s.eventsOf("EQ-1")
613		last := events[len(events)-1]
614		if last.Kind != eventPlanAdjust || last.Seq != events[len(events)-2].Seq+1 {
615			t.Fatalf("失败不应消耗序号: %+v", last)
616		}
617		if p.NextDue != "2026-01-11" {
618			t.Fatalf("下一到期日 = %q，想得到 2026-01-11", p.NextDue)
619		}
620		if err := s.save(); err != nil {
621			t.Fatal(err)
622		}
623		// 失败本身未写文件：保存前文件字节与之前一致（由后续成功保存覆盖）。
624		s = saveAndReopen(t, s)
625		if p := s.findPlan("EQ-1"); p.Content != "更换高效滤芯" || p.FirstDue != "2026-01-11" ||
626			p.IntervalDays != 60 || p.NextDue != "2026-01-11" {
627			t.Fatalf("重载后方案未保持: %+v", p)
628		}
629		if got := len(s.eventsOf("EQ-1")); got != 3 {
630			t.Fatalf("重载后履历数 = %d，想得到 3", got)
631		}
632	}
633	
634	// 命令行入口：参数错误退出码 2，业务失败退出码 1，成功输出新方案与日期。
635	func TestCmdAdjustExitCodes(t *testing.T) {
636		dir := t.TempDir()
637		var out, errBuf bytes.Buffer
638		if code := run([]string{"register", "--data-dir", dir, "--asset-id", "EQ-1", "--name", "打印机", "--location", "一楼"}, &out, &errBuf); code != 0 {
639			t.Fatalf("register: %d %s", code, errBuf.String())
640		}
641		if code := run([]string{"plan", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "更换滤芯",
642			"--first-due", "2026-11-01", "--interval-days", "90"}, &out, &errBuf); code != 0 {
643			t.Fatalf("plan: %d %s", code, errBuf.String())
644		}
645		// 参数错误：缺理由、无效日期、非正间隔、缺内容。
646		for _, args := range [][]string{
647			{"adjust", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "x", "--first-due", "2027-01-01", "--interval-days", "30"},
648			{"adjust", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "x", "--first-due", "2027-13-01", "--interval-days", "30", "--reason", "r"},
649			{"adjust", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "x", "--first-due", "2027-01-01", "--interval-days", "0", "--reason", "r"},
650			{"adjust", "--data-dir", dir, "--asset-id", "EQ-1", "--first-due", "2027-01-01", "--interval-days", "30", "--reason", "r"},
651		} {
652			out.Reset()
653			if code := run(args, &out, &errBuf); code != 2 {
654				t.Fatalf("%v 应以退出码 2 失败，得到 %d", args, code)
655			}
656		}
657		// 业务失败：未知资产、无计划。
658		out.Reset()
659		if code := run([]string{"adjust", "--data-dir", dir, "--asset-id", "NOPE", "--content", "x",
660			"--first-due", "2027-01-01", "--interval-days", "30", "--reason", "r"}, &out, &errBuf); code != 1 {
661			t.Fatalf("未知资产应以退出码 1 失败，得到 %d", code)
662		}
663		if code := run([]string{"register", "--data-dir", dir, "--asset-id", "EQ-2", "--name", "空调", "--location", "二楼"}, &out, &errBuf); code != 0 {
664			t.Fatal(code)
665		}
666		if code := run([]string{"adjust", "--data-dir", dir, "--asset-id", "EQ-2", "--content", "x",
667			"--first-due", "2027-01-01", "--interval-days", "30", "--reason", "r"}, &out, &errBuf); code != 1 {
668			t.Fatalf("无计划应以退出码 1 失败，得到 %d", code)
669		}
670		// 成功：输出新方案与日期。
671		out.Reset()
672		if code := run([]string{"adjust", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "更换高效滤芯",
673			"--first-due", "2027-01-01", "--interval-days", "60", "--reason", "型号升级"}, &out, &errBuf); code != 0 {
674			t.Fatalf("adjust 应成功，得到 %d: %s", code, errBuf.String())
675		}
676		for _, want := range []string{"保养内容: 更换高效滤芯", "保养间隔: 每 60 天", "首次到期日: 2027-01-01", "下一到期日: 2027-01-01"} {
677			if !strings.Contains(out.String(), want) {
678				t.Fatalf("输出缺少 %q:\n%s", want, out.String())
679			}
680		}
681		// plan 仍不能覆盖已有计划。
682		if code := run([]string{"plan", "--data-dir", dir, "--asset-id", "EQ-1", "--content", "覆盖",
683			"--first-due", "2028-01-01", "--interval-days", "30"}, &out, &errBuf); code != 1 {
684			t.Fatalf("已有计划时 plan 应拒绝，得到 %d", code)
685		}
686	}
